//! Emits the complete per-weapon table of every 1.8 BR (Athena) ranged weapon as Markdown: `weapons-table <install> [out.md]` (stdout when no path).
//! Everything is read through `fn_hitreg::data::load` (WID + `AthenaRangedWeapons` row + weapon actor Blueprint chain + fire-ability chain + projectile curve rows); nothing is typed in.
use fn_hitreg::data::{self, GunHit};
use fn_pose::ClipSourceDir;
use std::fmt::Write;

fn cell(s: &str) -> String { s.replace('|', "\\|") }
fn short(p: &str) -> &str { p.rsplit('/').next().unwrap_or(p) }

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let paks = fn_pak::PakSet::open_install(&a[1]).expect("open install");
    let src = ClipSourceDir::Pak(&paks);
    let mut guns: Vec<GunHit> = Vec::new();
    let mut skipped: Vec<String> = Vec::new();
    for wid in data::br_weapon_wids(&paks) {
        match data::load(&src, &wid) {
            // the BR ranged table only: melee / harvesting definitions use other tables
            Ok(g) if g.stat_table.ends_with("AthenaRangedWeapons") => guns.push(g),
            Ok(g) => skipped.push(format!("{} (stat table {})", g.wid, g.stat_table)),
            Err(e) => skipped.push(format!("{wid}: {e}")),
        }
    }
    let mut o = String::new();
    let _ = writeln!(o, "# 1.8 Battle Royale ranged weapon table\n");
    let _ = writeln!(o, "Generated by `cargo run --release -p fn-hitreg --bin weapons-table -- <install> parity/guns/weapons.md`. {} weapons (one per `WID_*_Athena_*` ranged item definition under `/Game/Athena/Items/Weapons/`). Every value is read from the 1.8 paks; units are the data's (cm, degrees, seconds, rounds per second).\n", guns.len());
    let _ = writeln!(o, "## Sources (property -> asset)\n");
    let _ = writeln!(o, "| Group | Fields | Source asset | Property |\n|---|---|---|---|");
    let _ = writeln!(o, "| Stat row | every column of section 2 | `/Game/Athena/Items/Weapons/AthenaRangedWeapons` (DataTable, row = WID `WeaponStatHandle.RowName`) | the column name in the header |");
    let _ = writeln!(o, "| Item | Rarity, Tier, MinLevel, TriggerType, AmmoData, PrimaryFireAbility, WeaponActorClass, ProjectileTemplate, bShouldUsePerfectAimWhenTargetingMinSpread | the weapon's `WID_*` asset (export 0 properties) | same names |");
    let _ = writeln!(o, "| Actor | aim flags, muzzle / tracer / beam FX, cameras, fire sounds, impact FX | `WeaponActorClass` Blueprint CDO, inheriting through its Blueprint parents | same names |");
    let _ = writeln!(o, "| Ability | target selection (shape, range, cone), max yaw, cues, effect class | `PrimaryFireAbility` Blueprint CDO (+ parents) | `EffectContainers[].TargetSelection.List[]`, `WeaponFireCue`, `AbilityTags` |");
    let _ = writeln!(o, "| Projectile | InitialSpeed, MaxSpeed | the projectile Blueprint CDO `InitialSpeed` / `MaxSpeed` (`CurveTableRowHandle`) evaluated at t=0 in its `AthenaProjectiles` CurveTable | row names listed in section 4 |\n");
    let _ = writeln!(o, "Notes (labelled):\n");
    let _ = writeln!(o, "* DATA: a WID names its stat row independently of its own name. WIDs whose row differs from their name are flagged in section 1 (the `_T02` common WIDs use the `_T03` row; `WID_Assault_SingleShot_Athena_SR_Ore_T03` uses the `..._VR_...` row). The row is what the game reads.");
    let _ = writeln!(o, "* DATA: headshot multiplier = `DamageZone_Critical`; environment (building) damage = `EnvDmg*`; damage falloff = the four points `Dmg{{PB,Mid,Long,MaxRange}}` at the ranges `Rng{{PB,Mid,Long,Max}}`. Which interpolation the native code applies between the points is native code, not in the data.");
    let _ = writeln!(o, "* DATA: the burst COUNT and burst interval are not serialized anywhere in the 1.8 files: the only burst columns are `BurstFiringRate` (rounds per second inside a burst) and `CartridgePerFire`. Triggers are the WID `TriggerType` (`Automatic`, `OnRelease`; absent = native default `OnPress`).");
    let _ = writeln!(o, "* DATA: a WID that serializes no `bShouldUsePerfectAimWhenTargetingMinSpread` gets the native class default `true` (constructor RVA 0x9164b0); the column shows the effective value.");
    let _ = writeln!(o, "* INFERENCE: hitscan vs projectile is decided by `ProjectileTemplate` being present on the WID (the fire ability class then is a `GenericProjectile*` ability). Charge columns are zero everywhere, so no charge-time weapon exists in the 1.8 BR table.\n");

    // 1: identity
    let _ = writeln!(o, "## 1. Identity, fire model and ammo\n");
    let _ = writeln!(o, "| WID | Stat row | Rarity | Tier | Trigger | Delivery | Ammo | CartridgePerFire | AmmoCostPerFire | PerfectAimAtMinSpread | Fire ability | Weapon actor (Blueprint chain) |\n|---|---|---|---|---|---|---|---|---|---|---|---|");
    for g in &guns {
        let name = short(&g.wid);
        let row = if g.row.replace("_T03", "").replace("_T02", "") == name.trim_start_matches("WID_").replace("AutoHigh", "Auto").replace("_T03", "").replace("_T02", "") { g.row.clone() } else { format!("{} (differs from WID name)", g.row) };
        let _ = writeln!(o, "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |", name, cell(&row), g.rarity.trim_start_matches("EFortRarity::"), g.tier.trim_start_matches("EFortItemTier::"), g.trigger.trim_start_matches("EFortWeaponTriggerType::"),
            g.projectile.as_ref().map_or("hitscan".into(), |p| format!("projectile {}", short(&p.template))), short(&g.ammo_path), g.stats.cartridge_per_fire, g.stats.ammo_cost_per_fire, g.perfect_aim_when_targeting_min_spread, short(&g.ability_path), g.pres.actor_chain.join(" < "));
    }

    // 2: every stat-row column (union in file order)
    let mut cols: Vec<String> = Vec::new();
    for g in &guns { for (c, _) in &g.stats.columns { if !cols.contains(c) { cols.push(c.clone()); } } }
    let _ = writeln!(o, "\n## 2. Stat row: every column (`AthenaRangedWeapons.<row>`)\n");
    let _ = writeln!(o, "Source of every cell: `/Game/Athena/Items/Weapons/AthenaRangedWeapons` DataTable, row = the `Stat row` of section 1, property = the column header. {} columns.\n", cols.len());
    let _ = writeln!(o, "| Row | {} |\n|---|{}", cols.join(" | "), "---|".repeat(cols.len()));
    for g in &guns {
        let cells: Vec<String> = cols.iter().map(|c| g.stats.columns.iter().find(|(n, _)| n == c).map_or("(absent)".to_owned(), |(_, v)| cell(v))).collect();
        let _ = writeln!(o, "| {} | {} |", g.row, cells.join(" | "));
    }

    // 3: ability
    let _ = writeln!(o, "\n## 3. Fire ability target selection (hit selection data)\n");
    let _ = writeln!(o, "| WID | Ability | Shape | Test | Source | Range | ConeYaw | ConePitch | ConeMinRadius | Filter | MaxTargets | MaxYawAngleToTarget | Effect class | Fire cue | Impact cues |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|");
    for g in &guns {
        for s in &g.ability.selections {
            let _ = writeln!(o, "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |", short(&g.wid), short(&g.ability.package), s.shape.trim_start_matches("EFortTargetSelectionShape::"), s.test_type.trim_start_matches("EFortTargetSelectionTestType::"),
                s.primary_source.trim_start_matches("EFortAbilityTargetingSource::"), s.range, s.cone_yaw, s.cone_pitch, s.cone_min_radius, s.actor_type_filter.trim_start_matches("EFortTargetSelectionFilter::"), s.max_targets,
                g.ability.max_yaw_angle_to_target.map_or("-".into(), |v| v.to_string()), g.ability.effect_classes.iter().map(|e| short(e)).collect::<Vec<_>>().join(","), g.ability.weapon_fire_cue.join(","), g.ability.impact_cues.join(","));
        }
        if g.ability.selections.is_empty() { let _ = writeln!(o, "| {} | {} | (no target selection serialized in the ability chain) | | | | | | | | | | | | |", short(&g.wid), short(&g.ability.package)); }
    }

    // 4: projectiles
    let _ = writeln!(o, "\n## 4. Projectile weapons\n");
    let _ = writeln!(o, "| WID | Projectile Blueprint | Curve table | InitialSpeed row | MaxSpeed row | InitialSpeed (cm/s, t=0) | MaxSpeed (cm/s, t=0) | ProjectileGravityScale | InitialLifeSpan | ProjectilePitchOffset |\n|---|---|---|---|---|---|---|---|---|---|");
    for g in guns.iter().filter(|g| g.projectile.is_some()) {
        let p = g.projectile.as_ref().unwrap();
        let _ = writeln!(o, "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |", short(&g.wid), p.template, p.table, p.initial_speed_row, p.max_speed_row, p.initial_speed, if p.max_speed.is_finite() { p.max_speed.to_string() } else { "unlimited (MaxSpeed 0)".into() }, p.gravity_scale.map_or("not serialized (engine default 1)".into(), |v| v.to_string()), p.life_span.map_or("-".into(), |v| v.to_string()), g.pres.projectile_pitch_offset);
    }

    // 5: presentation flags
    let _ = writeln!(o, "\n## 5. Weapon actor flags and FX (Blueprint CDO, inherited through the chain)\n");
    let _ = writeln!(o, "| WID | AimFromMuzzleAtCloseRange | MaintainAimDuringTargeting | UseScopeTargeting | Muzzle FX | Tracer | Beam | Camera base 3P | Camera targeting 3P | Fire sound[0] |\n|---|---|---|---|---|---|---|---|---|---|");
    for g in &guns {
        let p = &g.pres;
        let _ = writeln!(o, "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |", short(&g.wid), p.aim_from_muzzle_at_close_range, p.maintain_aim_during_targeting, p.use_scope_targeting,
            p.muzzle_particle.as_deref().map_or("-", short), p.tracer_template.as_deref().map_or("-", short), p.beam_particle.as_deref().map_or("-", short),
            p.camera_base_3p.as_deref().map_or("-", short), p.camera_targeting_3p.as_deref().map_or("-", short), p.fire_sounds.first().map_or("-", |x| short(&x.1)));
    }
    if !skipped.is_empty() { let _ = writeln!(o, "\n## Not ranged-table weapons (excluded)\n"); for s in &skipped { let _ = writeln!(o, "* {s}"); } }
    match a.get(2) { Some(p) => std::fs::write(p, o).expect("write"), None => print!("{o}") }
}
